#: Lista KO-leder starter med, i hver portal. Redigeres under KO-innstillinger.
STANDARD_EKSTERNE = ('Brann', 'Politi', 'AMK', 'LSKO')

#: Beskrivelsen fra «Ny hendelse» skrives i samme transaksjon som hendelsen.
BESKRIVELSE_VINDU = timedelta(seconds=10)


def fyll(apps, schema_editor):
    """Data **etter** skjemaet, aldri før (CLAUDE.md, «Migrasjoner»).

    1. Standardlista i hver portal som finnes.
    2. Pekeren til beskrivelsen for hendelsene som alt finnes: den første
       operatørlinja i hendelsen, skrevet av den som opprettet den, innen
       noen sekunder etter opprettelsen — nøyaktig det `opprett_hendelse`
       skrev. Linja hendelsen ble laget *fra* er eldre enn hendelsen, og
       faller utenfor vinduet. Treffer ingen, står
       hendelsen uten beskrivelse; det er det den hadde.
    """
    Vaktportal = apps.get_model('core', 'Vaktportal')
    EksternRessurs = apps.get_model('ko', 'EksternRessurs')
    for portal in Vaktportal.objects.all():
        for i, navn in enumerate(STANDARD_EKSTERNE):
            EksternRessurs.objects.get_or_create(
                portal=portal, navn=navn, defaults={'rekkefolge': (i + 1) * 10})

    Hendelse = apps.get_model('ko', 'Hendelse')
    Logglinje = apps.get_model('ko', 'Logglinje')
    for h in Hendelse.objects.filter(beskrivelse_linje__isnull=True).iterator():
        linje = (Logglinje.objects
                 .filter(hendelse_id=h.pk, kilde='operator', rot__isnull=True,
                         forfatter_navn=h.opprettet_av_navn,
                         registrert_at__gte=h.opprettet_at,
                         registrert_at__lte=h.opprettet_at + BESKRIVELSE_VINDU)
                 .order_by('id').first())
        if linje is not None:
            Hendelse.objects.filter(pk=h.pk).update(beskrivelse_linje=linje)



